WITH source AS (SELECT mktcode,tgtcode,bizdate,volume,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate DESC) AS lookback_row FROM `newzl`.`hsj_stock_hq_basic`), eligible AS (SELECT * FROM source WHERE lookback_row<=10), daily AS (SELECT mktcode,tgtcode,bizdate,MAX(volume) AS value FROM eligible GROUP BY mktcode,tgtcode,bizdate), lagged AS (SELECT mktcode,tgtcode,bizdate,value,LAG(value) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS previous FROM daily), metric AS (SELECT mktcode,tgtcode,bizdate,(value-previous)*100/NULLIF(ABS(previous),0) AS value FROM lagged), ranked AS (SELECT mktcode,tgtcode,bizdate,ROW_NUMBER() OVER(PARTITION BY bizdate ORDER BY value DESC,mktcode ASC,tgtcode ASC) AS rn,COUNT(*) OVER(PARTITION BY bizdate) AS population FROM metric), qualified AS (SELECT mktcode,tgtcode FROM ranked GROUP BY mktcode,tgtcode HAVING SUM(CASE WHEN rn<=CEIL(population*20/100.0) THEN 1 ELSE 0 END)>0) SELECT a.mktcode,a.tgtcode,a.bizdate FROM `newzl`.`hsj_stock_hq_basic` a JOIN qualified q ON q.mktcode=a.mktcode AND q.tgtcode=a.tgtcode WHERE a.bizdate='2026-04-14';
